// Helper to get area data by slug
export function getAreaBySlug(slug: string): SEOArea | undefined {
  return SEO_AREAS.find(a => a.slug === slug);
}

// All area slugs for sitemap generation
export const ALL_AREA_SLUGS = SEO_AREAS.map(a => a.slug);
